# Clean implementation: per marker, per (vertical_dir, horizontal_dir) pair from 4 combos, walk V2,H2 alternately, painting cells; stop when a 2-step along current axis fails.
def zig(H,W,mr,mc,vd,hd):
    s=set(); r,c=mr,mc; v,h=v*1 or 0,hd
    turn = (vd!=0)  # vertical first
    while True:
        ax,av = ('v' if turn else 'h'), vd if turn else hd
        nr,nc=r+h, c+(av and 1)*(vd)  # nonsense; redo properly
        break
    return None

def zigarm(H,W,r0,c0,vd,hd):
    s=set(); r,c=r0,c0; turn='v'
    while True:
        steps=0
        while steps<2 and 0<=r+ (vd if turn=='v' else 0)*1<H and False: pass
        # proper cell-level walk
        stepdir = vd if turn=='v' else 0  # hacky again; write plainly
        break
    return s

def arm(H,W,r,c,vd,hd,turn):
    s=set()
    vert = vd!=0 and turn
    while True:
        dr,dc = (vd,0) if vert else (0,hd)
        # move up to 2 steps
        rr,cc=r,c
        moved=False
        for _ in range(2):
            nr,nc=rr+dr,cc+dc
            if 0<=nr<H and 0<=nc<W:
                r,c=nr,nc; s.add((r,c)); moved=True
            else:
                # can't place even one -> try to continue? observed arms terminate whole run
                break
        if not moved: break
        vert = not vert
    return s

def gen(H,W,mr,mc):
    s=set()
    for vd in (1,-1):
        for hd in (1,-1):
            if vd==0 and hd==0: continue
            s|=arm(H,W,mr,mc,vd,hd,True)
            s|=arm(H,W,mr,mc,vd,hd,False)
    return s

