# Bresenham-style line drawing between pairs of markers: connect (a,b) with integer interpolation using standard algorithm.
def bres(a,b):
    (y1,x1),(y2,x2)=a,b
    dy,dx=y2-y1,x2-x1; sy=1 if dy>=0 else -1; sx=1 if dx>=0 else -1
    if abs(dy)>=abs(dx): P=(abs(dy)-abs(dx))/2; y=x1; stepx=((dy//dx)+1 if dx!=0 else 0)/dx if dx!=0 else 0
    else:
        P=(abs(dx)-abs(dy))/2; x=x1; stepx=((dy//dx)+1 if dx!=0 else 0)/dx if dx!=0 else 0
    y2_,x2_=None,None
    # simpler: iterate over major axis
    n=max(abs(dy),abs(dx))
    y=c=x=t=0; endy,yend=sy*n,sx*n
    while c<n:
        yield(int(y1+t),int(x1+c))
        if y==endy: y-=sy
        if x==endx: x-=sx
        c+=1
