    ms=[(i,j) for i in range(H) for j in range(W) if I_[i][j]!=bgc]
    pred=set()
    for a in range(len(ms)):
        for b_ in range(a+1,len(ms)):
            for (r,c) in bres(ms[a],ms[b_]):
